import{_ as p,a0 as t,w as r,s as o,I as n,x as a,a1 as i,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"YAML 使用入门 | LCTT x X-CMD","titleTemplate":false,"description":"YAML 使用入门 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"YAML 使用入门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"YAML 使用入门 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210917 Start using YAML now","title":"YAML 使用入门","tag":"202109","desc":""},"relativePath":"202109/20210917 Start using YAML now.md","filePath":"[post].md"}'),u={name:"202109/20210917 Start using YAML now.md"};function g(h,s,m,k,b,f){const l=t("Link");return r(),o("div",null,[s[25]||(s[25]=n("h1",{id:"yaml-使用入门",tabindex:"-1"},[a("YAML 使用入门 "),n("a",{class:"header-anchor",href:"#yaml-使用入门","aria-label":"Permalink to “YAML 使用入门”"},"​")],-1)),s[26]||(s[26]=n("blockquote",null,[n("p",null,"什么是 YAML，为什么我们现在应该开始使用它？")],-1)),s[27]||(s[27]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/23/095242fw0qzzp5fe6e565z.jpg",alt:""})],-1)),n("p",null,[i(l,{href:"https://yaml.org/"},{default:e(()=>[...s[0]||(s[0]=[a("YAML",-1)])]),_:1}),s[1]||(s[1]=a("（",-1)),s[2]||(s[2]=n("ruby",null,[a("YAML 不是标记语言"),n("rt",null,"YAML Ain't Markup Language")],-1)),s[3]||(s[3]=a("）是一种适宜阅读理解的数据序列化语言。它的语法简单而易于阅读。它不包含引号、打开和关闭的标签或大括号。它不包含任何可能使人类难以解析嵌套规则的东西。你可以看一下你的 YAML 文档就知道它在什么。",-1))]),s[28]||(s[28]=d(`<h3 id="yaml-特性" tabindex="-1">YAML 特性 <a class="header-anchor" href="#yaml-特性" aria-label="Permalink to “YAML 特性”">​</a></h3><p>YAML 有一些超级特性，使其优于其他序列化格式：</p><ul><li>易于略读。</li><li>易于使用。</li><li>可在编程语言之间移植。</li><li>敏捷语言的原生数据结构。</li><li>支持通用工具的一致模型。</li><li>支持一次性处理。</li><li>表现力和可扩展性。</li></ul><p>我将通过一些例子进一步向你展示 YAML 的强大。</p><p>你能弄清楚下面发生了什么吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------</span></span>
<span class="line"><span># My grocery list</span></span>
<span class="line"><span>groceries:</span></span>
<span class="line"><span>    - Milk</span></span>
<span class="line"><span>    - Eggs</span></span>
<span class="line"><span>    - Bread</span></span>
<span class="line"><span>    - Butter</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>上面的例子包含了一个简单的杂货购物清单，它是一个完全格式化的 YAML 文档。在 YAML 中，字符串不加引号，而列表需要简单的连字符和空格。一个 YAML 文档以 <code>---</code> 开始，以 <code>...</code> 结束，但它们是可选的。YAML中的注释以 <code>#</code> 开始。</p><p>缩进是 YAML 的关键。缩进必须包含空格，而不是制表符。虽然所需的空格数量是灵活的，但保持一致是个好主意。</p><h3 id="基本元素" tabindex="-1">基本元素 <a class="header-anchor" href="#基本元素" aria-label="Permalink to “基本元素”">​</a></h3><h4 id="集合" tabindex="-1">集合 <a class="header-anchor" href="#集合" aria-label="Permalink to “集合”">​</a></h4><p>YAML 有两种类型的集合。列表（用于序列）和字典（用于映射）。列表是键值对，每个值都在一个新的行中，以连字符和空格开始。字典也是键值对，每个值都是一个映射，包含一个键、一个冒号和空格以及一个值。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># My List</span></span>
<span class="line"><span>groceries:</span></span>
<span class="line"><span>    - Milk</span></span>
<span class="line"><span>    - Eggs</span></span>
<span class="line"><span>    - Bread</span></span>
<span class="line"><span>    - Butter</span></span>
<span class="line"><span></span></span>
<span class="line"><span># My dictionary</span></span>
<span class="line"><span>contact:</span></span>
<span class="line"><span>    name: Ayush Sharma</span></span>
<span class="line"><span>    email: myemail@example.com</span></span></code></pre></div><p>列表和字典经常被结合起来，以提供更复杂的数据结构。列表可以包含字典，而字典可以包含列表。</p><h4 id="字符串" tabindex="-1">字符串 <a class="header-anchor" href="#字符串" aria-label="Permalink to “字符串”">​</a></h4><p>YAML 中的字符串不需要加引号。多行字符串可以用 <code>|</code> 或 <code>&gt;</code> 来定义。前者保留了换行符，而后者则没有。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_string: |</span></span>
<span class="line"><span>    This is my string.</span></span>
<span class="line"><span>    It can contain many lines.</span></span>
<span class="line"><span>    Newlines are preserved.</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_string_2: &gt;</span></span>
<span class="line"><span>    This is my string.</span></span>
<span class="line"><span>    This can also contain many lines.</span></span>
<span class="line"><span>    Newlines aren&#39;t preserved and all lines are folded.</span></span></code></pre></div><h4 id="锚点" tabindex="-1">锚点 <a class="header-anchor" href="#锚点" aria-label="Permalink to “锚点”">​</a></h4><p>YAML 可以通过节点锚点来获得可重复的数据块。<code>&amp;</code> 字符定义了一个数据块，以后可以用 <code>*</code> 来引用。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>billing_address: &amp;add1</span></span>
<span class="line"><span>    house: B1</span></span>
<span class="line"><span>    street: My Street</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shipping_address: *add1</span></span></code></pre></div>`,22)),n("p",null,[s[5]||(s[5]=a("至止你对 YAML 的了解就足以让你开始工作了。你可以使用在线 YAML 解析器来测试。如果你每天都与 YAML 打交道，那么 ",-1)),i(l,{href:"https://yaml.org/refcard.html"},{default:e(()=>[...s[4]||(s[4]=[a("这个方便的备忘单",-1)])]),_:1}),s[6]||(s[6]=a(" 会对你有所帮助。",-1))]),n("p",null,[n("em",null,[s[8]||(s[8]=a("这篇文章最初发表在",-1)),i(l,{href:"https://notes.ayushsharma.in/2021/08/introduction-to-yaml"},{default:e(()=>[...s[7]||(s[7]=[a("作者的个人博客",-1)])]),_:1}),s[9]||(s[9]=a("上，并经授权改编。",-1))])]),s[29]||(s[29]=n("hr",null,null,-1)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),i(l,{href:"https://opensource.com/article/21/9/intro-yaml"},{default:e(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/21/9/intro-yaml",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),i(l,{href:"https://opensource.com/users/ayushsharma"},{default:e(()=>[...s[12]||(s[12]=[a("Ayush Sharma",-1)])]),_:1}),s[17]||(s[17]=a(" 选题：",-1)),i(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:e(()=>[...s[14]||(s[14]=[a("geekpi",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:e(()=>[...s[21]||(s[21]=[a("Linux中国",-1)])]),_:1}),s[24]||(s[24]=a(" 荣誉推出",-1))])])}const A=p(u,[["render",g]]);export{M as __pageData,A as default};
